'use strict';
(()=>{
 const messages={az:{title:'Rezervasiyanı ləğv etmək istəyirsiniz?',description:'Təsdiq etdikdən sonra vaxt digər müştərilər üçün açılacaq.',button:'Rezervasiyanı ləğv et',home:'Ana səhifəyə qayıt',done:'Rezervasiya ləğv edildi.',invalid:'Keçid etibarsızdır və ya rezervasiyanı artıq onlayn ləğv etmək mümkün deyil. Salonla əlaqə saxlayın.',network:'Cavab alınmadı. İnterneti yoxlayın və yenidən cəhd edin.',pending:'Gözləyin…'},ru:{title:'Отменить запись?',description:'После подтверждения время станет доступно другим клиентам.',button:'Отменить запись',home:'Вернуться на сайт',done:'Запись отменена.',invalid:'Ссылка недействительна или запись уже нельзя отменить онлайн. Свяжитесь с салоном.',network:'Ответ не получен. Проверьте интернет и повторите попытку.',pending:'Подождите…'},en:{title:'Cancel your booking?',description:'After confirmation, this time will become available to other clients.',button:'Cancel booking',home:'Return to website',done:'Your booking has been cancelled.',invalid:'This link is invalid or the booking can no longer be cancelled online. Please contact the salon.',network:'No response received. Check your connection and try again.',pending:'Please wait…'}};
 const $=s=>document.querySelector(s);let language='az',state='';try{const saved=localStorage.getItem('ilkersevim.language');if(messages[saved])language=saved;}catch{}
 const match=location.hash.match(/^#([0-9a-f-]{36})\.([0-9a-f-]{36})$/i);if(!match)state='invalid';
 function render(){const m=messages[language];document.documentElement.lang=language;$('#title').textContent=m.title;$('#description').textContent=m.description;$('#cancel').textContent=m.button;$('#home').textContent=m.home;$('#status').textContent=state?m[state]:'';$('#cancel').hidden=state==='done'||state==='invalid';for(const b of document.querySelectorAll('[data-lang]'))b.setAttribute('aria-pressed',String(b.dataset.lang===language));}
 for(const b of document.querySelectorAll('[data-lang]'))b.addEventListener('click',()=>{language=b.dataset.lang;try{localStorage.setItem('ilkersevim.language',language);}catch{}render();});
 $('#cancel').addEventListener('click',async()=>{if(!match)return;const button=$('#cancel');button.disabled=true;state='pending';render();try{const response=await fetch('/api/bookings/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:match[1],token:match[2]}),cache:'no-store',signal:AbortSignal.timeout(15000)});state=response.ok?'done':[404,409].includes(response.status)?'invalid':'network';}catch{state='network';}finally{button.disabled=false;render();}});
 render();
})();
